<?php
require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/includes/layout.php';require_login('student');$q=$pdo->prepare('SELECT p.*,c.title FROM payments p JOIN courses c ON c.id=p.course_id WHERE p.user_id=? ORDER BY p.created_at DESC');$q->execute([current_user()['id']]);$payments=$q->fetchAll();$hasPending=(bool)array_filter($payments,fn($p)=>$p['status']==='pending');start_page('Payment history','payments'); ?>
<div class="mb-4 flex items-center justify-between gap-3"><p class="muted">Your enrollment payments and provider references.</p><a class="btn-secondary" href="<?= e(app_url('student/payments.php')) ?>">Refresh status</a></div><?php if($hasPending): ?><div class="alert alert-success mb-4">A payment is awaiting provider confirmation. This list refreshes automatically while a payment is pending.</div><script>setTimeout(()=>location.reload(),12000);</script><?php endif ?><div class="table-wrap"><table><thead><tr><th>Course</th><th>Method</th><th>Reference</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td class="font-semibold text-slate-700"><?= e($p['title']) ?></td><td><?= e(strtoupper($p['provider'])) ?></td><td class="font-mono text-xs"><?= e($p['reference']) ?></td><td>KSh <?= number_format((float)$p['amount_kes'],2) ?></td><td><span class="badge badge-<?= e($p['status']==='success'?'success':($p['status']==='failed'?'failed':'pending')) ?>"><?= e($p['status']) ?></span></td><td><?= e(date('M j, Y H:i',strtotime($p['created_at']))) ?></td></tr><?php endforeach ?><?php if(!$payments): ?><tr><td colspan="6" class="py-10 text-center text-slate-500">No payment records yet.</td></tr><?php endif ?></tbody></table></div><?php end_page(); ?>
